sealed class AudrenFfiException: kotlin.Exception() {
    
    class InvalidInput(
        
        val `reason`: kotlin.String
        ) : AudrenFfiException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class Crypto(
        
        val `reason`: kotlin.String
        ) : AudrenFfiException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<AudrenFfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): AudrenFfiException = FfiConverterTypeAudrenFfiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeAudrenFfiError : FfiConverterRustBuffer<AudrenFfiException> {
    override fun read(buf: ByteBuffer): AudrenFfiException {
        

        return when(buf.getInt()) {
            1 -> AudrenFfiException.InvalidInput(
                FfiConverterString.read(buf),
                )
            2 -> AudrenFfiException.Crypto(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: AudrenFfiException): ULong {
        return when(value) {
            is AudrenFfiException.InvalidInput -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is AudrenFfiException.Crypto -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: AudrenFfiException, buf: ByteBuffer) {
        when(value) {
            is AudrenFfiException.InvalidInput -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is AudrenFfiException.Crypto -> {
                buf.putInt(2)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalString: FfiConverterRustBuffer<kotlin.String?> {
    override fun read(buf: ByteBuffer): kotlin.String? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterString.read(buf)
    }

    override fun allocationSize(value: kotlin.String?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterString.allocationSize(value)
        }
    }

    override fun write(value: kotlin.String?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterString.write(value, buf)
        }
    }
}




